#!/usr/bin/env python3
"""Compute schema-v1 reference data for CSX-130_Q1 from local package files."""

from __future__ import annotations

import json
import re
from collections import defaultdict
from datetime import date, datetime
from pathlib import Path
from typing import Any


TASK_ID = "CSX-130_Q1"
PACKAGE_ID = "CSX-130"
EVENT_ID = PACKAGE_ID
TARGET_FAMILY = "ophelia_wind_rain_phase_score_ledger"

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_004_Locked_anchor_report.html",
    "data/event_reports/event_reports_005_Locked_event_anchor_Hurricane_Ophelia_eastern_Atlantic-to-Europe_track.json",
    "data/physical_hazard/physical_hazard_002_Open-Meteo_historical_wind_rain_point_API.json",
    "data/physical_hazard/physical_hazard_004_NASA_POWER_daily_point_weather_API.json",
]


def repo_root() -> Path:
    here = Path(__file__).resolve()
    for candidate in [here.parent, *here.parents]:
        package_path = candidate / "event_packages" / "standard_event_packages" / "packages" / PACKAGE_ID
        if package_path.is_dir():
            return candidate
    raise RuntimeError("Could not locate repository root")


def package_dir() -> Path:
    return repo_root() / "event_packages" / "standard_event_packages" / "packages" / PACKAGE_ID


def task_dir() -> Path:
    return Path(__file__).resolve().parent


def load_json(rel_path: str) -> Any:
    return json.loads((package_dir() / rel_path).read_text(encoding="utf-8-sig"))


def read_text(rel_path: str) -> str:
    return (package_dir() / rel_path).read_text(encoding="utf-8-sig", errors="replace")


def finite(values: list[Any]) -> list[float]:
    return [float(value) for value in values if value is not None]


def extreme_with_time(times: list[str], values: list[Any], mode: str) -> dict[str, Any]:
    numeric = [(idx, float(value)) for idx, value in enumerate(values) if value is not None]
    idx, value = min(numeric, key=lambda item: item[1]) if mode == "min" else max(numeric, key=lambda item: item[1])
    return {"time": times[idx], "value": round(value, 3)}


def days_between(date_a: str, date_b: str) -> int:
    a = date.fromisoformat(date_a)
    b = date.fromisoformat(date_b)
    return abs((b - a).days)


def parse_title(html: str) -> str:
    match = re.search(r"<title>(.*?)</title>", html, flags=re.IGNORECASE | re.DOTALL)
    return re.sub(r"\s+", " ", match.group(1)).strip() if match else ""


def report_date_flags(html: str) -> dict[str, Any]:
    lower = html.lower()
    has_post_tropical = "post-tropical cyclone" in lower
    has_ireland_uk = "ireland and the united kingdom" in lower
    has_transition_date = "october 15, 2017" in lower
    has_impact_date = "october 16, 2017" in lower
    return {
        "transition_date": "2017-10-15" if has_post_tropical and has_transition_date else None,
        "impact_date": "2017-10-16" if has_ireland_uk and has_impact_date else None,
        "transition_before_impact_day": has_post_tropical and has_transition_date,
        "ireland_uk_impact_on_2017_10_16": has_ireland_uk and has_impact_date,
    }


def scoring_rubric() -> dict[str, Any]:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "Requested JSON score ledger",
                "points": 3,
                "description": (
                    "Provides the requested JSON shape with target_family, three score rows, rejected_path, "
                    "final_label, and a concise interpretation."
                ),
                "partial_credit": "Award 1-2 points for a mostly complete object with one missing row or misplaced field.",
            },
            {
                "name": "Local wind-pressure score",
                "points": 5,
                "description": (
                    "Reports 111.6 km/h gust, 61.4 km/h wind, 989.6 hPa pressure, 1.0 hour lag, wind peak on "
                    "2017-10-16, and score 5/5."
                ),
                "partial_credit": "Award 2-4 points for correct thresholds with minor value or timing errors.",
            },
            {
                "name": "Rainfall-primary rejection",
                "points": 4,
                "description": (
                    "Reports 2.4 mm impact-day rainfall, 13.1 mm total, 0.183 share, 0.9 mm maximum hourly "
                    "rainfall, 2017-10-11 precipitation peak, 2017-10-16 wind peak, 5-day gap, and score 0/4."
                ),
                "partial_credit": "Award 1-3 points for the correct rejection with incomplete numeric anchors.",
            },
            {
                "name": "Daily product phase check",
                "points": 3,
                "description": (
                    "Uses 25.02 mm total precipitation, 20171011 precipitation peak, 20171016 wind peak, "
                    "13.87 m/s maximum daily wind, and 49.932 km/h conversion."
                ),
                "partial_credit": "Award 1-2 points for correct dates or values but missing the conversion or phase comparison.",
            },
            {
                "name": "Score arithmetic and decision",
                "points": 2,
                "description": "Applies the score rule and identifies a 5/5 wind-pressure path versus a 0/4 rainfall-primary path.",
                "partial_credit": "Award 1 point for the right final label with incomplete score arithmetic.",
            },
            {
                "name": "Report timing anchors",
                "points": 2,
                "description": "Uses the report timing: transition before 2017-10-16 and Ireland/UK impact on 2017-10-16.",
                "partial_credit": "Award 1 point for mentioning only one of the two timing anchors.",
            },
            {
                "name": "No unverified loss transfer",
                "points": 1,
                "description": "Avoids converting cloud imagery, population values, or report language into unverified damage, casualty, or loss claims.",
                "partial_credit": "Award 0.5 points for a concise answer that omits those claims but does not explicitly guard against them.",
            },
        ],
    }


def main() -> None:
    event = load_json("metadata/event.json")
    anchor = load_json("data/event_reports/event_reports_005_Locked_event_anchor_Hurricane_Ophelia_eastern_Atlantic-to-Europe_track.json")
    report_html = read_text("data/event_reports/event_reports_004_Locked_anchor_report.html")
    open_meteo = load_json("data/physical_hazard/physical_hazard_002_Open-Meteo_historical_wind_rain_point_API.json")
    power = load_json("data/physical_hazard/physical_hazard_004_NASA_POWER_daily_point_weather_API.json")

    hourly = open_meteo["hourly"]
    times = hourly["time"]
    daily_precip: defaultdict[str, float] = defaultdict(float)
    for time_value, precip in zip(times, hourly["precipitation"]):
        if precip is not None:
            daily_precip[time_value[:10]] += float(precip)

    impact_date = "2017-10-16"
    max_gust = extreme_with_time(times, hourly["wind_gusts_10m"], "max")
    max_wind = extreme_with_time(times, hourly["wind_speed_10m"], "max")
    min_pressure = extreme_with_time(times, hourly["pressure_msl"], "min")
    max_hourly_precip = extreme_with_time(times, hourly["precipitation"], "max")
    gust_pressure_lag_hours = round(
        (datetime.fromisoformat(min_pressure["time"]) - datetime.fromisoformat(max_gust["time"])).total_seconds() / 3600,
        3,
    )

    local_precip_total = round(sum(finite(hourly["precipitation"])), 3)
    impact_day_precip = round(daily_precip[impact_date], 3)
    impact_day_precip_share = round(impact_day_precip / local_precip_total, 3)
    daily_precip_peak_date = max(daily_precip, key=daily_precip.get)
    daily_wind_peak_date = max_wind["time"][:10]
    peak_date_gap_days = days_between(daily_precip_peak_date, daily_wind_peak_date)

    power_params = power["properties"]["parameter"]
    power_precip = {date_key: float(value) for date_key, value in power_params["PRECTOTCORR"].items()}
    power_wind = {date_key: float(value) for date_key, value in power_params["WS10M"].items()}
    nasa_precip_total = round(sum(power_precip.values()), 3)
    nasa_max_precip_date = max(power_precip, key=power_precip.get)
    nasa_max_wind_date = max(power_wind, key=power_wind.get)
    nasa_max_daily_wind_ms = round(max(power_wind.values()), 3)
    nasa_max_daily_wind_kmh = round(nasa_max_daily_wind_ms * 3.6, 3)

    report_flags = report_date_flags(report_html)

    wind_tests = {
        "gust_ge_100_kmh": max_gust["value"] >= 100,
        "wind_ge_50_kmh": max_wind["value"] >= 50,
        "pressure_le_995_hpa": min_pressure["value"] <= 995,
        "pressure_lag_le_2h": 0 <= gust_pressure_lag_hours <= 2,
        "wind_peak_on_2017_10_16": daily_wind_peak_date == impact_date,
    }
    rain_tests = {
        "impact_day_share_ge_0_25": impact_day_precip_share >= 0.25,
        "local_precip_peak_matches_wind_peak": daily_precip_peak_date == daily_wind_peak_date,
        "max_hourly_precip_ge_5_mm": max_hourly_precip["value"] >= 5,
        "daily_product_precip_peak_matches_wind_peak": nasa_max_precip_date == nasa_max_wind_date,
    }
    timing_tests = {
        "transition_before_impact_day": bool(report_flags["transition_before_impact_day"]),
        "ireland_uk_impact_on_2017_10_16": bool(report_flags["ireland_uk_impact_on_2017_10_16"]),
    }

    wind_score = sum(wind_tests.values())
    rain_score = sum(rain_tests.values())
    timing_score = sum(timing_tests.values())
    final_label = (
        "wind_led_post_tropical_ireland_uk_pathway"
        if wind_score >= 4 and rain_score <= 1 and timing_score == 2
        else "mixed_or_unresolved_pathway"
    )

    score_ledger = {
        "wind_pressure_path": {
            "score": wind_score,
            "max_score": 5,
            "tests": wind_tests,
            "key_values": {
                "hour_count": len(times),
                "max_gust_time": max_gust["time"],
                "max_gust_kmh": max_gust["value"],
                "max_wind_time": max_wind["time"],
                "max_wind_kmh": max_wind["value"],
                "min_pressure_time": min_pressure["time"],
                "min_pressure_hpa": min_pressure["value"],
                "gust_pressure_lag_hours": gust_pressure_lag_hours,
                "daily_wind_peak_date": daily_wind_peak_date,
            },
        },
        "rain_primary_path": {
            "score": rain_score,
            "max_score": 4,
            "tests": rain_tests,
            "key_values": {
                "impact_day_precip_mm": impact_day_precip,
                "total_precip_mm": local_precip_total,
                "impact_day_precip_share": impact_day_precip_share,
                "max_hourly_precip_time": max_hourly_precip["time"],
                "max_hourly_precip_mm": max_hourly_precip["value"],
                "local_precip_peak_date": daily_precip_peak_date,
                "local_wind_peak_date": daily_wind_peak_date,
                "peak_date_gap_days": peak_date_gap_days,
            },
        },
        "post_tropical_timing": {
            "score": timing_score,
            "max_score": 2,
            "tests": timing_tests,
            "key_values": {
                "report_title": parse_title(report_html),
                "transition_date": report_flags["transition_date"],
                "impact_date": report_flags["impact_date"],
            },
        },
    }

    primary_gt = {
        "target_family": TARGET_FAMILY,
        "final_label": final_label,
        "score_summary": {
            "wind_pressure_path": wind_score,
            "rain_primary_path": rain_score,
            "post_tropical_timing": timing_score,
        },
        "ledger_rows": [
            {"id": "wind_pressure_path", "result": "pass", "v": [111.6, 61.4, 989.6, 1.0, "2017-10-16"]},
            {"id": "rain_primary_path", "result": "reject", "v": [2.4, 13.1, 0.183, 0.9, 5]},
            {"id": "daily_product_phase_check", "result": "pass", "v": [25.02, 20171011, 20171016, 49.932]},
            {"id": "post_tropical_timing", "result": "pass", "v": ["2017-10-15", "2017-10-16"]},
        ],
        "rejected_path": "rainfall_primary",
    }

    output = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "key_values": {
            "event": {
                "event_name": event["event_name"],
                "hazard_family": event["hazard_family"],
                "region": event["region"],
                "temporal_window": {
                    "start_date": anchor["temporal_window"]["start_date"],
                    "end_date": anchor["temporal_window"]["end_date"],
                },
            },
            "score_ledger": score_ledger,
            "daily_product": {
                "precip_total_mm": nasa_precip_total,
                "max_precip_date": nasa_max_precip_date,
                "max_wind_date": nasa_max_wind_date,
                "max_daily_wind_ms": nasa_max_daily_wind_ms,
                "max_daily_wind_kmh": nasa_max_daily_wind_kmh,
            },
            "decision_rule": {
                "final_label": final_label,
                "rule": "wind score >= 4, rain-primary score <= 1, and timing score = 2",
                "one_sentence_interpretation": (
                    "The 2017-10-16 impact is best calibrated as wind-led after transition: "
                    "the wind-pressure score is 5/5 while the rainfall-primary score is 0/4."
                ),
            },
        },
        "tolerances": {
            "wind_kmh_abs": 0.1,
            "pressure_hpa_abs": 0.1,
            "lag_hours_abs": 0.1,
            "precip_mm_abs": 0.05,
            "ratio_abs": 0.01,
            "accepted_result_states": ["pass", "reject"],
        },
        "rubric": scoring_rubric(),
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
            "notes": "Values are extracted from local CSX-130 data and assembled into a wind-rain phase score ledger.",
        },
    }

    (task_dir() / "computed_gt.json").write_text(json.dumps(output, indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
